// ============ MENU ART ASSETS ============
'use strict';
const MENU_BG_DATA_URI = "data:image/jpeg;base64,";
const EMBLEM_DATA_URI = "data:image/svg+xml;base64,";

(function initMenuAssets() {
  const startScreen = document.getElementById('start-screen');
  if (startScreen) {
    startScreen.style.background = 'linear-gradient(180deg, rgba(6, 10, 6, 0.88) 0%, rgba(6, 10, 6, 0.25) 35%, rgba(6, 10, 6, 0.25) 65%, rgba(6, 10, 6, 0.92) 100%), url("' + MENU_BG_DATA_URI + '") center / cover no-repeat';
  }
  const dimmedBg = 'linear-gradient(rgba(6, 10, 6, 0.85), rgba(6, 10, 6, 0.85)), url("' + MENU_BG_DATA_URI + '") center / cover no-repeat';
  for (const id of ['pause-menu', 'death-screen', 'victory-screen']) {
    const el = document.getElementById(id);
    if (el) el.style.background = dimmedBg;
  }
  let emblem = document.getElementById('menu-emblem');
  if (!emblem && startScreen) {
    const h1 = startScreen.querySelector('h1');
    if (h1 && h1.parentNode) {
      emblem = document.createElement('img');
      emblem.id = 'menu-emblem';
      emblem.className = 'menu-emblem';
      emblem.alt = 'Squad Emblem';
      h1.parentNode.insertBefore(emblem, h1);
    }
  }
  if (emblem) {
    emblem.src = EMBLEM_DATA_URI;
    emblem.style.display = 'block';
    emblem.style.margin = '0 auto 14px auto';
    emblem.style.width = '112px';
    emblem.style.height = 'auto';
  }
})();
